const {default: pTimeout, TimeoutError} = await load('./index.js');

async function test() {
  const slowPromise = new Promise(resolve => setTimeout(() => resolve('slow'), 1000));
  const decorated = pTimeout(slowPromise, { milliseconds: Infinity });
  try {
    await decorated;
    throw new Error('Should have timed out');
  } catch (error) {
    if (error instanceof TimeoutError) {
      // This should not happen with Infinity
      throw new Error('Unexpected timeout with Infinity');
    }
  }
}

await test();
